.include "hdr.asm"

.section ".rodata1" superfree

snesfont:
.incbin "pvsneslibfont.pic"

; Void Serpent sprite graphics, generated by tools/gengfx.py into src/gfx/.
;
; These MUST be assembled here rather than kept as initialised C arrays: the
; devkitsnes linker discards main.obj's ".data" section, which would silently
; zero-fill the graphics and leave every sprite invisible. ".rodata1" is a
; superfree section and survives linking, exactly like the console font above.
;
; Tiles are 4bpp 8x8, 16 bytes each; palettes are 32 bytes (16 colours).

vsgfx_tiles:
.incbin "gfx/vsgfx_tiles.bin"

vpal_snake:
.incbin "gfx/vpal_snake.bin"

vpal_food:
.incbin "gfx/vpal_food.bin"

vpal_bonus:
.incbin "gfx/vpal_bonus.bin"

vpal_shard:
.incbin "gfx/vpal_shard.bin"

vpal_fx:
.incbin "gfx/vpal_fx.bin"

vpal_portal:
.incbin "gfx/vpal_portal.bin"

.ends
